// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address newMigrator, address rewardToken) public {
        vm.assume(rewardToken != address(0));
        vm.assume(newMigrator != address(0));
        vm.assume(newMigrator != address(0xdead));

        // Call setMigrator with fuzzed address
        c.setMigrator(newMigrator);

        // Call addReward to trigger the state difference
        c.addReward(rewardToken);

        // The general rule: after addReward, migrator should equal the address passed to setMigrator
        address currentMigrator = c.migrator();
        assertTrue(currentMigrator == newMigrator);
    }
}

